<template>
  <AuthLayout :loading="checking" :showInfoPanel="false">
    <AuthCard>
      <!-- Error state -->
      <div v-if="error_message" class="flex flex-col items-center gap-4 py-4">
        <div class="flex items-center justify-center size-12 rounded-full bg-destructive/10">
          <Icon icon="mdi:close" class="size-6 text-destructive" />
        </div>
        <p class="text-sm font-medium text-destructive text-center">{{ error_message }}</p>
      </div>

      <!-- Success state -->
      <div v-else-if="success_message" class="flex flex-col items-center gap-4 py-4">
        <div class="flex items-center justify-center size-12 rounded-full bg-success/10">
          <Icon icon="mdi:check" class="size-6 text-success" />
        </div>
        <p class="text-sm font-medium text-success text-center">{{ success_message }}</p>
      </div>

      <template #actions>
        <q-btn
          unelevated
          color="primary"
          text-color="white"
          :label="$t('sign_in')"
          class="auth-submit-btn"
          @click="goLogin()"
        />
        <div class="mt-3 flex justify-center">
          <ResendVerifyEmail :email="email" />
        </div>
      </template>
    </AuthCard>
  </AuthLayout>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import axios from 'axios';
import { api, getClientAuthorization } from 'pages/APIs';
import { LocalStorage } from 'quasar';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { defineComponent, ref } from 'vue';
import ResendVerifyEmail from 'src/pages/User/ResendVerifyEmail.vue';
import { encodeQueryData } from 'src/utils/general';
import { AuthLayout, AuthCard } from 'src/components/Auth';

export default defineComponent({
  components: {
    ResendVerifyEmail,
    AuthLayout,
    AuthCard,
  },
  setup() {
    return {
      email: ref(''),
      code: ref(''),
      success_message: ref(''),
      error_message: ref(''),
      checking: ref(false),
    };
  },
  watch: {
    error_message(new_val: any) {
      if (new_val !== '') {
        this.checking = false;
        this.success_message = '';
      }
    },
    success_message(new_val: any) {
      if (new_val !== '') {
        this.checking = false;
        this.error_message = '';
      }
    },
  },
  mounted() {
    LocalStorage.remove('user_details');
    this.processEmailCodeVaidattion();
  },
  methods: {
    async processEmailCodeVaidattion() {
      try {
        this.checking = true;
        this.getEmailAndCode();
        if (!this.code || !this.email) {
          this.displayError(this.$t('resend_email'));
          return;
        }
        await this.verifyEmail();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        this.displayError(msg);
      } finally {
        this.checking = false;
      }
    },

    getEmailAndCode() {
      for (const [key, value] of Object.entries(this.$route.query)) {
        if (key === 'code') this.code = String(value);
        if (key === 'email') this.email = String(value);
      }
    },

    goLogin() {
      this.$router.push('/');
    },

    async verifyEmail() {
      const data = { email: this.email, code: this.code };
      const querystring = encodeQueryData(data);
      this.checking = true;
      let response: any;
      response = await axios.get(api.confirm_email + '?' + querystring, {
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          Authorization: getClientAuthorization(),
        },
      });

      if (response.data?.hasOwnProperty('success') && response.data.success === false) {
        throw { message: response.data.message };
      }

      if (response.data?.hasOwnProperty('success') && response.data.success === true) {
        this.success_message = response.data.message;
      }
    },

    displayError(message: any) {
      this.error_message = message || this.$t('general_login_error');
    },
  },
});
</script>

<style scoped lang="scss">
.auth-submit-btn {
  width: 100%;
  height: 44px;
  font-weight: 500;
  border-radius: 0.5rem;
}
</style>
